import React from "react";
import { NavLink } from "react-router-dom";
import {
    Box,
    Button,
    Flex,
    FormControl,
    FormLabel,
    Heading,
    Input,
    Text,
    useColorModeValue,
} from "@chakra-ui/react";
import DefaultAuth from "layouts/auth/Default";
import Card from 'components/card/Card';
import illustration from "assets/img/auth/auth.png";
import axios from "axios";

function ForgotPassword() {
    //Handle auth info
    const [email, setEmail] = React.useState('');
    const handleSignUp = async (event: any) => {
        event.preventDefault();
        const serverApi = process.env.REACT_APP_API;
        const current_ip: any = await axios.get('https://api.ipify.org/?format=json');
        const response = await axios.post(`${serverApi}` + `forgotpassword`, {
            "email": email,
            "ip": current_ip.data.ip
        });
        if (response.data.status == false) {
            alert(response.data.result)
        } else {
            window.location.href = '/';
        }
    };
    const textColor = useColorModeValue("navy.700", "white");
    const textColorSecondary = "gray.400";
    const textColorDetails = useColorModeValue("navy.700", "secondaryGray.600");
    const textColorBrand = useColorModeValue("brand.500", "white");
    const brandStars = useColorModeValue("brand.500", "brand.400");
    const [show, setShow] = React.useState(false);
    const handleShow = () => setShow(!show);

    return (
        <DefaultAuth illustrationBackground={illustration} image={illustration}>
            <Card py='15px' alignItems='center' flexDirection='column' w='100%'>
                <Flex
                    maxW={{ base: "100%", md: "max-content" }}
                    w='100%'
                    mx={{ base: "auto", lg: "0px" }}
                    me='auto'
                    h='100%'
                    align='center'
                    justifyContent='space-between'
                    mb={{ base: "30px", md: "60px" }}
                    px={{ base: "25px", md: "0px" }}
                    mt={{ base: "20px", md: "7vh" }}
                    flexDirection='column'>
                    <Box me='auto' w='100%'>
                        <Heading color={textColor} fontSize='30px' mb='30px' textAlign='center' w='100%'>
                            Forgot password
                        </Heading>
                    </Box>
                    <Flex

                        zIndex='2'
                        direction='column'
                        w={{ base: "100%", md: "420px" }}
                        maxW='100%'
                        background='transparent'
                        borderRadius='15px'
                        mx={{ base: "auto", lg: "unset" }}
                        me='auto'
                        mb={{ base: "20px", md: "auto" }}>
                        <Text w='100%' textAlign='center'>Enter your email to get password reset email
                        </Text>
                        <FormControl my='10px'>
                            <FormLabel
                                display='flex'
                                ms='4px'
                                fontSize='sm'
                                fontWeight='500'
                                mx='auto'
                                color={textColor}
                                mb='8px'>
                                Email<Text color={brandStars}>*</Text>
                            </FormLabel>
                            <Input
                                isRequired={true}
                                variant='auth'
                                fontSize='sm'
                                ms={{ base: "0px", md: "0px" }}
                                type='email'
                                placeholder='Enter your email'
                                mb='24px'
                                fontWeight='500'
                                size='lg'
                                onChange={(event) => setEmail(event.target.value)}
                            />
                            <Button
                                fontSize='sm'
                                variant='brand'
                                fontWeight='500'
                                w='100%'
                                h='50'
                                mb='24px'
                                onClick={handleSignUp}
                            >
                                Send password reset email
                            </Button>
                        </FormControl>
                        <Flex
                            flexDirection='column'
                            justifyContent='center'
                            alignItems='center'
                            maxW='100%'
                            mt='0px'>
                            <Text color={textColorDetails} fontWeight='400' fontSize='14px' textAlign='center'>
                                Don’t have any account?


                                <NavLink to='/auth/sign-up'>
                                    <Text
                                        color={textColorBrand}
                                        as='span'
                                        ms='5px'
                                        fontWeight='500'>
                                        Sign Up
                                    </Text>
                                </NavLink>
                                <br />
                                <NavLink to='/auth/sign-in'>
                                    <Text
                                        color={textColorBrand}
                                        as='span'
                                        ms='5px'
                                        fontWeight='500'>
                                        Sign In
                                    </Text>
                                </NavLink>
                            </Text>
                        </Flex>
                    </Flex>
                </Flex>
            </Card>
        </DefaultAuth>
    );
}

export default ForgotPassword;
